"""
X2AP Protocol Messages Definition Module for PCAP Analysis.
This module provides predefined X2AP (X2 Application Protocol) message definitions and factory functions
for creating awaited messages used in PCAP file analysis.
The module defines AwaitedMessage objects that can be used to verify the presence and correctness of
specific X2AP protocol messages in network traffic captures.

:copyright:     Nokia Networks
:author:        Piotr Brzezicki, Mateusz Potoniec
:maintainer:    Piotr Brzezicki, Mateusz Potoniec
:contact:       piotr.brzezicki@nokia.com, mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.parsers.pcap_checker import Checker
    from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
    from taf.rfrl.utilities.parsers.pcap_checker.messages import x2ap_messages, ngap_messages

    pci_5g = '50'
    awaited_messages = [
        x2ap_messages.SGNB_ADDITION_REQUEST,
        x2ap_messages.create_sgnb_addition_request_acknowledge(pci_5g),
        x2ap_messages.SGNB_RECONFIGURATION_COMPLETE,
        x2ap_messages.SNS_STATUS_TRANSFER
    ]

    forbidden_messages = [
        x2ap_messages.SGNB_MODIFICATION_REQUEST_FAILURE_INFORMATION,
        x2ap_messages.SGNB_RELEASE_REQUEST
    ]

    pcap_provider = PcapProvider()
    checker = Checker(pcap_provider=pcap_provider)
    checker.expect_flow(
        pcap_file=pcap_file,
        display_filter='x2ap',
        awaited_messages=awaited_messages,
        forbidden_messages=forbidden_messages
    )
"""


from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import HasInspector


SGNB_ADDITION_REQUEST = AwaitedMessage(
    name='SgNBAdditionRequest',
    find_by=[HasInspector('x2ap.SgNBAdditionRequest_element')],
    verify_by=[],
)


SGNB_CHANGE_REQUIRED = AwaitedMessage(
    name='SgNBChangeRequired',
    find_by=[HasInspector('x2ap.SgNBChangeRequired_element')],
    verify_by=[],
)


SGNB_CHANGE_CONFIRM = AwaitedMessage(
    name='SgNBChangeConfirm',
    find_by=[HasInspector('x2ap.SgNBChangeConfirm_element')],
    verify_by=[],
)


SGNB_RECONFIGURATION_COMPLETE = AwaitedMessage(
    name='SgNBReconfigurationComplete',
    find_by=[HasInspector('x2ap.SgNBReconfigurationComplete_element')],
    verify_by=[],
)


SNS_STATUS_TRANSFER = AwaitedMessage(
    name='SNStatusTransfer',
    find_by=[HasInspector('x2ap.SNStatusTransfer_element')],
    verify_by=[],
)


SGNB_RELEASE_REQUIRED = AwaitedMessage(
    name='SgNBReleaseRequired',
    find_by=[HasInspector('x2ap.SgNBReleaseRequired_element')],
    verify_by=[],
)


SGNB_MODIFICATION_REQUEST_FAILURE_INFORMATION = AwaitedMessage(
    name='SgNBModificationRequest',
    find_by=[HasInspector('x2ap.SgNBModificationRequest_element')],
    verify_by=[HasInspector('nr-rrc.scgFailureInfo_element')],
)


SGNB_RELEASE_REQUEST = AwaitedMessage(
    name='SgNBReleaseRequest',
    find_by=[HasInspector('x2ap.SgNBReleaseRequest_element')],
    verify_by=[],
)


def create_sgnb_addition_request_acknowledge(phys_cell_id: str) -> AwaitedMessage:
    """
    Factory function to create an AwaitedMessage for SgNBAdditionRequestAcknowledge.
    Create a parameterized AwaitedMessage for SgNBAdditionRequestAcknowledge with a specific physical cell ID.

    :param phys_cell_id: The physical cell ID to verify in the message.
    :return: An AwaitedMessage instance with the specified physical cell ID verification.
    """

    return AwaitedMessage(
        name='SgNBAdditionRequestAcknowledge',
        find_by=[HasInspector('x2ap.SgNBAdditionRequestAcknowledge_element')],
        verify_by=[HasInspector('nr-rrc.physCellId', str(phys_cell_id))],
    )
